-- Fog Wallet initial schema.
-- Keep this migration aligned with the live D1 database.
-- IDs and timestamps are generated by the API; all sensitive writes must be server-authorized.

CREATE TABLE IF NOT EXISTS users (
  id TEXT PRIMARY KEY,
  telegram_sub TEXT NOT NULL UNIQUE,
  username TEXT,
  display_name TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS card_designs (
  id TEXT PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  series TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('standard', 'limited')),
  design_json TEXT NOT NULL CHECK (json_valid(design_json)),
  asset_key TEXT,
  edition_size INTEGER CHECK (edition_size IS NULL OR edition_size > 0),
  enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  CHECK (
    (kind = 'limited' AND edition_size IS NOT NULL) OR
    (kind = 'standard' AND edition_size IS NULL)
  )
);

CREATE TABLE IF NOT EXISTS activation_codes (
  id TEXT PRIMARY KEY,
  code_hash TEXT NOT NULL UNIQUE,
  design_id TEXT NOT NULL REFERENCES card_designs(id),
  intended_user_id TEXT REFERENCES users(id),
  created_by_admin TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  expires_at INTEGER,
  revoked_at INTEGER,
  claimed_at INTEGER,
  claimed_by_user_id TEXT REFERENCES users(id),
  CHECK (
    (claimed_at IS NULL AND claimed_by_user_id IS NULL) OR
    (claimed_at IS NOT NULL AND claimed_by_user_id IS NOT NULL)
  )
);

CREATE TABLE IF NOT EXISTS cards (
  id TEXT PRIMARY KEY,
  serial TEXT NOT NULL UNIQUE,
  owner_user_id TEXT NOT NULL REFERENCES users(id),
  design_id TEXT NOT NULL REFERENCES card_designs(id),
  activation_code_id TEXT NOT NULL UNIQUE REFERENCES activation_codes(id),
  receipt_id TEXT NOT NULL UNIQUE,
  certificate_payload TEXT NOT NULL CHECK (json_valid(certificate_payload)),
  certificate_signature TEXT NOT NULL,
  issued_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS user_card_settings (
  user_id TEXT PRIMARY KEY REFERENCES users(id),
  selected_design_id TEXT REFERENCES card_designs(id),
  featured_card_id TEXT REFERENCES cards(id),
  customization_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(customization_json)),
  public_enabled INTEGER NOT NULL DEFAULT 0 CHECK (public_enabled IN (0, 1)),
  updated_at INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS card_transfers (
  id TEXT PRIMARY KEY,
  card_id TEXT NOT NULL REFERENCES cards(id),
  sender_user_id TEXT NOT NULL REFERENCES users(id),
  recipient_user_id TEXT REFERENCES users(id),
  token_hash TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'accepted', 'cancelled', 'expired')),
  created_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL,
  accepted_at INTEGER,
  cancelled_at INTEGER,
  CHECK (recipient_user_id IS NULL OR recipient_user_id <> sender_user_id)
);

CREATE TABLE IF NOT EXISTS card_events (
  id TEXT PRIMARY KEY,
  card_id TEXT NOT NULL REFERENCES cards(id),
  actor_user_id TEXT REFERENCES users(id),
  event_type TEXT NOT NULL
    CHECK (event_type IN (
      'issued',
      'transfer_created',
      'transfer_accepted',
      'transfer_cancelled',
      'transfer_expired',
      'featured'
    )),
  metadata_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(metadata_json)),
  created_at INTEGER NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_card_designs_catalog
  ON card_designs(enabled, kind, series);

CREATE INDEX IF NOT EXISTS idx_activation_codes_design_created
  ON activation_codes(design_id, created_at);

CREATE INDEX IF NOT EXISTS idx_cards_owner_issued
  ON cards(owner_user_id, issued_at DESC);

CREATE INDEX IF NOT EXISTS idx_transfers_recipient_status
  ON card_transfers(recipient_user_id, status, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_card_events_card_created
  ON card_events(card_id, created_at DESC);

CREATE UNIQUE INDEX IF NOT EXISTS idx_one_pending_transfer_per_card
  ON card_transfers(card_id) WHERE status = 'pending';

CREATE TRIGGER IF NOT EXISTS trg_activation_code_design_limit
BEFORE INSERT ON activation_codes
WHEN COALESCE((SELECT kind FROM card_designs WHERE id = NEW.design_id), '') <> 'limited'
  OR (SELECT COUNT(*) FROM activation_codes WHERE design_id = NEW.design_id) >=
     (SELECT edition_size FROM card_designs WHERE id = NEW.design_id)
BEGIN
  SELECT RAISE(ABORT, 'activation_code_design_limit');
END;

CREATE TRIGGER IF NOT EXISTS trg_activation_code_claim_rules
BEFORE UPDATE OF claimed_at, claimed_by_user_id ON activation_codes
WHEN (
    OLD.claimed_at IS NULL AND NEW.claimed_at IS NOT NULL AND (
      OLD.revoked_at IS NOT NULL
      OR (OLD.expires_at IS NOT NULL AND OLD.expires_at <= NEW.claimed_at)
      OR (OLD.intended_user_id IS NOT NULL AND OLD.intended_user_id <> NEW.claimed_by_user_id)
    )
  ) OR (
    OLD.claimed_at IS NOT NULL AND (
      NEW.claimed_at IS NOT OLD.claimed_at
      OR NEW.claimed_by_user_id IS NOT OLD.claimed_by_user_id
    )
  )
BEGIN
  SELECT RAISE(ABORT, 'activation_code_claim_invalid');
END;

CREATE TRIGGER IF NOT EXISTS trg_card_activation_match
BEFORE INSERT ON cards
WHEN NOT EXISTS (
  SELECT 1 FROM activation_codes ac
  WHERE ac.id = NEW.activation_code_id AND ac.design_id = NEW.design_id
    AND ac.claimed_by_user_id = NEW.owner_user_id AND ac.claimed_at IS NOT NULL
    AND ac.revoked_at IS NULL
)
BEGIN
  SELECT RAISE(ABORT, 'card_activation_mismatch');
END;

CREATE TRIGGER IF NOT EXISTS trg_card_owner_requires_transfer
BEFORE UPDATE OF owner_user_id ON cards
WHEN NEW.owner_user_id <> OLD.owner_user_id AND NOT EXISTS (
  SELECT 1 FROM card_transfers t WHERE t.card_id = OLD.id
    AND t.sender_user_id = OLD.owner_user_id AND t.recipient_user_id = NEW.owner_user_id
    AND t.status = 'accepted'
)
BEGIN
  SELECT RAISE(ABORT, 'card_owner_change_requires_accepted_transfer');
END;

CREATE TRIGGER IF NOT EXISTS trg_transfer_sender_is_owner
BEFORE INSERT ON card_transfers
WHEN COALESCE((SELECT owner_user_id FROM cards WHERE id = NEW.card_id), '') <> NEW.sender_user_id
BEGIN
  SELECT RAISE(ABORT, 'transfer_sender_not_owner');
END;

-- Replace the trigger to ensure only a pending transfer can be accepted.
DROP TRIGGER IF EXISTS trg_transfer_accept_valid;

CREATE TRIGGER trg_transfer_accept_valid
BEFORE UPDATE OF status ON card_transfers
WHEN NEW.status = 'accepted' AND (
  OLD.status <> 'pending'
  OR NEW.recipient_user_id IS NULL
  OR NEW.accepted_at IS NULL
  OR NEW.expires_at <= NEW.accepted_at
  OR COALESCE((SELECT owner_user_id FROM cards WHERE id = NEW.card_id), '') <> OLD.sender_user_id
)
BEGIN
  SELECT RAISE(ABORT, 'transfer_accept_invalid');
END;

CREATE TRIGGER IF NOT EXISTS trg_user_card_settings_valid_insert
BEFORE INSERT ON user_card_settings
WHEN (
  NEW.selected_design_id IS NOT NULL
  AND COALESCE((SELECT kind FROM card_designs WHERE id = NEW.selected_design_id), '') <> 'standard'
) OR (
  NEW.featured_card_id IS NOT NULL
  AND COALESCE((SELECT owner_user_id FROM cards WHERE id = NEW.featured_card_id), '') <> NEW.user_id
)
BEGIN
  SELECT RAISE(ABORT, 'user_card_settings_invalid');
END;

CREATE TRIGGER IF NOT EXISTS trg_user_card_settings_valid_update
BEFORE UPDATE OF user_id, selected_design_id, featured_card_id ON user_card_settings
WHEN (
  NEW.selected_design_id IS NOT NULL
  AND COALESCE((SELECT kind FROM card_designs WHERE id = NEW.selected_design_id), '') <> 'standard'
) OR (
  NEW.featured_card_id IS NOT NULL
  AND COALESCE((SELECT owner_user_id FROM cards WHERE id = NEW.featured_card_id), '') <> NEW.user_id
)
BEGIN
  SELECT RAISE(ABORT, 'user_card_settings_invalid');
END;
